import { NextResponse } from "next/server"
import { PrismaClient } from "@prisma/client"

const prisma = new PrismaClient()

// POST /api/videos → Neues Video speichern
export async function POST(req: Request) {
  try {
    const data = await req.json()
    const { title, creator, videoUrl, thumbnail } = data

    if (!title || !videoUrl) {
      return NextResponse.json({ error: "Missing required fields" }, { status: 400 })
    }

    const video = await prisma.videoapp_videos.create({
      data: {
        title,
        creator,
        videoUrl,
        thumbnail,
      },
    })

    return NextResponse.json(video, { status: 201 })
  } catch (error) {
    console.error("❌ Error saving video:", error)
    return NextResponse.json({ error: "Failed to save video" }, { status: 500 })
  }
}

// GET /api/videos → Alle Videos holen
export async function GET() {
  const videos = await prisma.videoapp_videos.findMany({
    orderBy: { uploadedAt: "desc" },
  })
  return NextResponse.json(videos)
}